                  d.setMobilePanel?.(d.mobilePanel === defaultPanel && d.activeTool === id ? "" : defaultPanel);
                }
              }}
            >
              <Icon size={23} />
              <span>{d.t(id, label)}</span>
            </button>
          ))}
        </aside>
        {toolRailOverflow.canScrollDown ? (
          <button
            className="tool-rail-more"
            type="button"
            aria-label={d.t("moreTools", "More tools")}
